head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf90002";
scwin.v_str = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — screenDivCd, message

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.v_str = '' + dma_vo.get("currIsoNm") + '';
        await scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf90002.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_116", fn: function(){ return ((dma_pageContext.get("screenDivCd") ?? "") === 'applResult'); } }, { id: "c_otherwise_121", fn: function(){ return (!(((dma_pageContext.get("screenDivCd") ?? "") === 'applResult'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bndMktactTpCd", fn: function () { return String(String((dma_pageContext.get("bndMktactTpCd") ?? ""))); } },
        { childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("applIsuNm") ?? ""))); } },
        { childId: "ipt_stdCd_2", fn: function () { return String(String((dma_pageContext.get("stdCd") ?? ""))); } },
        { childId: "ipt_listTerm", fn: function () { return String(String((dma_pageContext.get("listTerm") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const fm = (document.SendForm || { elements: [] });
        await scwin.showMessage();
        const listFee = parseInt(Del_MoneyComma_Value($c.util.getComponent('ipt_listFee').getValue()));
        const anulfee = parseInt(Del_MoneyComma_Value($c.util.getComponent('ipt_anulfee').getValue()));
        const div_obj = $c.util.getComponent("txt_sumfee");
        if ($c.util.getComponent('ipt_listFee').getValue()=== "N/A" || $c.util.getComponent('ipt_anulfee').getValue()=== "N/A") {
            $c.util.getComponent("ipt_sumfee").setValue("N/A");
        } else {
            $c.util.getComponent("ipt_sumfee").setValue($c.num.formatMoney(listFee + anulfee + ""));
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf90002.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_print_onclick = async function(e){
    try {
        await scwin.print()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf90002.btn_print_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90002.btn_self_onclick' }); }
};

/**
 * @method
 * @name btn_print_2_onclick
 * @description btn_print_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_print_2_onclick = async function(e){
    try {
        await scwin.print()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf90002.btn_print_2_onclick' }); }
};

/**
 * @method
 * @name btn_NewListAppl_onclick
 * @description btn_NewListAppl 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_NewListAppl_onclick = function(e){
    try {
        scwin.NewListAppl()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90002.btn_NewListAppl_onclick' }); }
};

/**
 * @method
 * @name btn_self_2_onclick
 * @description btn_self_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_2_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90002.btn_self_2_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_print
 * @description print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_downloadFile_direct
 * @description download File direct 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_downloadFile_direct = async function () {
    try { return await $c.data.downFile("/upload/downloadFile.do", "", ($c.util.getComponent("dma_downloadFileDirectReq") ? $c.util.getComponent("dma_downloadFileDirectReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name showMessage
 * @description show Message 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showMessage = async function () {
    const message = (String(((dma_pageContext.get("message") ?? "")) == null ? '' : ((dma_pageContext.get("message") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("message") ?? "")) == null ? '' : ((dma_pageContext.get("message") ?? ""))));
    await $c.win.alert(message);
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function () {
    const formName = (document.newReportForm || { elements: [] });
    await scwin.tx_fn_print();
};

/**
 * @method
 * @name printOld
 * @description print Old 처리
 * @returns {void}
 * @hidden N
 */
scwin.printOld = function () {
    const rexName = "JLDBNF90002";
    const dataType = "XML";
    const formName = (document.SendForm || { elements: [] });
    fn_PrintPreView_JLDBNF90002(rexName, dataType, formName);
};

/**
 * @method
 * @name downloadFile_direct
 * @description download File direct 처리
 * @param {*} _contn_id _contn_id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.downloadFile_direct = async function (_contn_id) {
    const fm = (document.downloadForm || { elements: [] });
    if (_contn_id === '1') {
        $c.util.getComponent("dma_printReq").set("orgnFileNm", "사업자등록증(서울사옥).jpg");
    } else {
        if (_contn_id === '2') {
            $c.util.getComponent("dma_printReq").set("orgnFileNm", "통장사본_채권상장수수료.jpg");
        } else {
            if (_contn_id === '3') {
                $c.util.getComponent("dma_printReq").set("orgnFileNm", "통장사본_채권연부과금.jpg");
            }
        }
    }
    fm.action = '/upload/downloadFile.do';
    $c.util.getComponent("dma_printReq").set("method", 'downloadFileAttach');
    await scwin.tx_downloadFile_direct();
};

/**
 * @method
 * @name NewListAppl
 * @description New List Appl 처리
 * @returns {void}
 * @hidden N
 */
scwin.NewListAppl = function () {
    const parentfm = parent.opener.document.SendForm;
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).NewListAppl(parentfm, ((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById('bnd_mktact_tp_cd')) && ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById('bnd_mktact_tp_cd')).getValue) ? ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById('bnd_mktact_tp_cd')).getValue() : ''));
    $c.win.closePopup();
};
